CREATE TABLE IF NOT EXISTS schema_versions(version integer PRIMARY KEY);
CREATE TABLE restaurants(id text PRIMARY KEY, name text NOT NULL, address text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', goal integer NOT NULL DEFAULT 150000 CHECK(goal>0));
CREATE TABLE profiles(id text PRIMARY KEY, name text NOT NULL, role text NOT NULL CHECK(role IN ('SUPER_ADMIN','OWNER','MANAGER','WAITER','CHEF','BARTENDER','STOCK_MANAGER','PURCHASING','ACCOUNTANT')));
CREATE TABLE memberships(profile_id text REFERENCES profiles, restaurant_id text REFERENCES restaurants, role text NOT NULL, PRIMARY KEY(profile_id,restaurant_id,role));
CREATE TABLE sessions(token text PRIMARY KEY, profile_id text NOT NULL REFERENCES profiles, expires_at timestamptz NOT NULL);
CREATE TABLE dining_tables(id text PRIMARY KEY, restaurant_id text NOT NULL REFERENCES restaurants, number integer NOT NULL, capacity integer NOT NULL CHECK(capacity>0), status text NOT NULL DEFAULT 'free' CHECK(status IN ('free','occupied','cleaning','unavailable')), UNIQUE(restaurant_id,number));
CREATE TABLE ingredients(id text PRIMARY KEY, restaurant_id text NOT NULL REFERENCES restaurants, name text NOT NULL, unit text NOT NULL CHECK(unit IN ('g','ml','unit')), threshold numeric NOT NULL CHECK(threshold>=0), cost numeric NOT NULL CHECK(cost>=0));
CREATE TABLE stock_lots(id text PRIMARY KEY, ingredient_id text NOT NULL REFERENCES ingredients, quantity numeric NOT NULL CHECK(quantity>=0), reserved numeric NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=quantity), expires_on date NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), location text NOT NULL DEFAULT 'Réserve', supplier text NOT NULL DEFAULT 'Démo');
CREATE TABLE menu_items(id text PRIMARY KEY, restaurant_id text NOT NULL REFERENCES restaurants, name text NOT NULL, category text NOT NULL, price integer NOT NULL CHECK(price>=0), station text NOT NULL CHECK(station IN ('kitchen','bar')), description text NOT NULL DEFAULT '', enabled boolean NOT NULL DEFAULT true);
CREATE TABLE recipe_ingredients(menu_id text NOT NULL REFERENCES menu_items, ingredient_id text NOT NULL REFERENCES ingredients, quantity numeric NOT NULL CHECK(quantity>0), PRIMARY KEY(menu_id,ingredient_id));
CREATE TABLE table_sessions(id text PRIMARY KEY, table_id text NOT NULL REFERENCES dining_tables, opened_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz);
CREATE UNIQUE INDEX one_open_session ON table_sessions(table_id) WHERE closed_at IS NULL;
CREATE TABLE orders(id text PRIMARY KEY, restaurant_id text NOT NULL REFERENCES restaurants, session_id text REFERENCES table_sessions, channel text NOT NULL CHECK(channel IN ('staff','takeaway','qr')), status text NOT NULL DEFAULT 'active' CHECK(status IN ('pending','active','paid','cancelled')), customer_name text NOT NULL DEFAULT '', contact text NOT NULL DEFAULT '', desired_at timestamptz, created_by text REFERENCES profiles, created_at timestamptz NOT NULL DEFAULT now(), idempotency_key text NOT NULL UNIQUE);
CREATE TABLE order_items(id text PRIMARY KEY, order_id text NOT NULL REFERENCES orders, menu_id text NOT NULL REFERENCES menu_items, name text NOT NULL, price integer NOT NULL CHECK(price>=0), quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 50), station text NOT NULL CHECK(station IN ('kitchen','bar')), status text NOT NULL DEFAULT 'waiting' CHECK(status IN ('waiting','preparing','ready','served','cancelled')), note text NOT NULL DEFAULT '', material_cost numeric NOT NULL DEFAULT 0);
CREATE TABLE stock_reservations(id text PRIMARY KEY, item_id text NOT NULL REFERENCES order_items, lot_id text NOT NULL REFERENCES stock_lots, quantity numeric NOT NULL CHECK(quantity>0), status text NOT NULL DEFAULT 'reserved' CHECK(status IN ('reserved','consumed','released','wasted')));
CREATE TABLE stock_movements(id text PRIMARY KEY, restaurant_id text NOT NULL REFERENCES restaurants, lot_id text NOT NULL REFERENCES stock_lots, quantity numeric NOT NULL, type text NOT NULL, reason text NOT NULL, actor text REFERENCES profiles, reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_declarations(id text PRIMARY KEY, session_id text REFERENCES table_sessions, order_id text REFERENCES orders, amount integer NOT NULL CHECK(amount>0), method text NOT NULL CHECK(method IN ('card','cash','other')), actor text NOT NULL REFERENCES profiles, created_at timestamptz NOT NULL DEFAULT now(), CHECK(session_id IS NOT NULL OR order_id IS NOT NULL));
CREATE UNIQUE INDEX session_payment_once ON payment_declarations(session_id) WHERE session_id IS NOT NULL;
CREATE UNIQUE INDEX order_payment_once ON payment_declarations(order_id) WHERE order_id IS NOT NULL;
CREATE TABLE reservations(id text PRIMARY KEY, restaurant_id text NOT NULL REFERENCES restaurants, name text NOT NULL, contact text NOT NULL, guests integer NOT NULL CHECK(guests BETWEEN 1 AND 20), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, table_id text REFERENCES dining_tables, status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','confirmed','arrived','declined','cancelled','no_show')), note text NOT NULL DEFAULT '', CHECK(ends_at>starts_at));
CREATE TABLE suppliers(id text PRIMARY KEY, restaurant_id text NOT NULL REFERENCES restaurants, name text NOT NULL, contact text NOT NULL, lead_days integer NOT NULL DEFAULT 2);
CREATE TABLE purchase_orders(id text PRIMARY KEY, restaurant_id text NOT NULL REFERENCES restaurants, supplier_id text NOT NULL REFERENCES suppliers, ingredient_id text NOT NULL REFERENCES ingredients, quantity numeric NOT NULL CHECK(quantity>0), received numeric NOT NULL DEFAULT 0 CHECK(received>=0 AND received<=quantity), due_on date NOT NULL, status text NOT NULL DEFAULT 'confirmed' CHECK(status IN ('confirmed','partial','received','cancelled')));
CREATE TABLE receipts(id text PRIMARY KEY, purchase_id text NOT NULL REFERENCES purchase_orders, lot_id text NOT NULL REFERENCES stock_lots, quantity numeric NOT NULL CHECK(quantity>0), actor text NOT NULL REFERENCES profiles, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE shifts(id text PRIMARY KEY, restaurant_id text NOT NULL REFERENCES restaurants, profile_id text NOT NULL REFERENCES profiles, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, CHECK(ends_at>starts_at));
CREATE TABLE time_entries(id text PRIMARY KEY, restaurant_id text NOT NULL REFERENCES restaurants, profile_id text NOT NULL REFERENCES profiles, event text NOT NULL CHECK(event IN ('start','break','resume','end')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE expenses(id text PRIMARY KEY, restaurant_id text NOT NULL REFERENCES restaurants, label text NOT NULL, amount integer NOT NULL CHECK(amount>0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customers(id text PRIMARY KEY, restaurant_id text NOT NULL REFERENCES restaurants, name text NOT NULL, contact text NOT NULL, consent boolean NOT NULL DEFAULT false, points integer NOT NULL DEFAULT 0 CHECK(points>=0));
CREATE TABLE loyalty_transactions(id text PRIMARY KEY, customer_id text NOT NULL REFERENCES customers, points integer NOT NULL, reason text NOT NULL, actor text NOT NULL REFERENCES profiles, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications(id text PRIMARY KEY, restaurant_id text NOT NULL REFERENCES restaurants, message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification_reads(notification_id text REFERENCES notifications, profile_id text REFERENCES profiles, PRIMARY KEY(notification_id,profile_id));
CREATE TABLE audit_logs(id text PRIMARY KEY, restaurant_id text NOT NULL REFERENCES restaurants, actor text REFERENCES profiles, action text NOT NULL, object_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX orders_restaurant_date ON orders(restaurant_id,created_at);
CREATE INDEX items_order ON order_items(order_id);
CREATE INDEX lots_ingredient ON stock_lots(ingredient_id,expires_on);
CREATE INDEX reservations_time ON reservations(restaurant_id,starts_at,ends_at);
CREATE INDEX audit_restaurant ON audit_logs(restaurant_id,created_at);
DO $$ DECLARE t record; BEGIN FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='public' LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t.tablename); END LOOP; END $$;
INSERT INTO schema_versions VALUES(1);
